import React, { useState, useEffect, useMemo } from 'react';
import MasterPortfolio from './MasterPortfolio';
import GSTClientFormModal from '../Clientform/GSTClientFormModal';
import { mockBackend } from '../../services/mockBackend';
import { Client, JurisdictionType } from '../../types';

const GSTPortfolio: React.FC = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [search, setSearch] = useState('');
  const [jurisdictionFilter, setJurisdictionFilter] = useState<JurisdictionType | 'All'>('All');
  const [sectorFilter, setSectorFilter] = useState<string>('All');
  const [rangeFilter, setRangeFilter] = useState<string>('All');
  const [showDataOptions, setShowDataOptions] = useState(false);
  const [clients, setClients] = useState<Client[]>([]);

  useEffect(() => {
    const load = async () => {
      const data = await mockBackend.getClients();
      setClients(data.filter(c => !!c.gstProfile));
    };
    load();
  }, [refreshTrigger]);

  const stats = useMemo(() => {
    const total = clients.length;
    const active = clients.filter(c => c.status === 'Active Filing').length;
    const caseStudy = clients.filter(c => c.status === 'Case-by-Case').length;
    const inactive = clients.filter(c => c.status.startsWith('Inactive')).length;
    return { total, active, caseStudy, inactive };
  }, [clients]);

  // Derived unique lists for dropdowns
  const sectors = useMemo(() => {
    const s = new Set<string>();
    clients.forEach(c => {
      if (c.gstProfile?.jurisdictionType === 'State' && c.gstProfile.sector) {
        s.add(c.gstProfile.sector);
      }
    });
    return Array.from(s).sort();
  }, [clients]);

  const ranges = useMemo(() => {
    const r = new Set<string>();
    clients.forEach(c => {
      if (c.gstProfile?.jurisdictionType === 'Center' && c.gstProfile.range) {
        r.add(c.gstProfile.range);
      }
    });
    return Array.from(r).sort();
  }, [clients]);

  const handleJurisdictionChange = (val: string) => {
    setJurisdictionFilter(val as any);
    setSectorFilter('All');
    setRangeFilter('All');
  };

  const handleExportCSV = () => {
    const headers = ["Legal Name", "Trade Name", "Mobile", "GSTIN", "Status", "Jurisdiction", "Sector/Range"];
    const rows = clients.map(c => [
      c.legalName,
      c.tradeName,
      c.mobile,
      c.gstProfile?.gstin,
      c.status,
      c.gstProfile?.jurisdictionType,
      c.gstProfile?.jurisdictionType === 'State' ? c.gstProfile.sector : c.gstProfile?.range
    ]);
    const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "gst_clients.csv");
    link.click();
    setShowDataOptions(false);
  };

  const handleImportTemplateCSV = () => {
    const headers = ["Legal Name", "Trade Name", "Mobile", "GSTIN", "Status", "Jurisdiction", "Sector/Range"];
    const csvContent = [headers].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "gst_template.csv");
    link.click();
    setShowDataOptions(false);
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (e) => {
      const text = e.target?.result as string;
      const rows = text.split('\n').slice(1);
      let successCount = 0;
      for (const row of rows) {
        const cols = row.split(',');
        if (cols.length < 4) continue;
        const gstin = cols[3]?.trim();
        if (!gstin) continue;
        try {
          await mockBackend.saveClient({
            legalName: cols[0]?.trim(),
            tradeName: cols[1]?.trim(),
            mobile: cols[2]?.trim(),
            status: 'Active Filing',
            gstProfile: {
              gstin,
              username: '',
              password: '',
              gstStatus: 'Active',
              regDate: new Date().toISOString().split('T')[0],
              regType: 'Regular',
              filingFreq: 'Monthly',
              constitution: 'Proprietorship',
              stakeholders: [],
              jurisdictionType: (cols[5]?.trim() as any) || 'State',
              sector: cols[6]?.trim() || '',
            }
          });
          successCount++;
        } catch (err) {}
      }
      alert(`Import complete: ${successCount} entries added.`);
      setRefreshTrigger(p => p + 1);
      setShowDataOptions(false);
    };
    reader.readAsText(file);
  };

  return (
    <div className="flex flex-col h-full space-y-3 pb-4 overflow-hidden">
      {/* Consolidated Toolbar */}
      <div className="flex flex-col lg:flex-row items-center gap-3 bg-white p-2.5 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">

        {/* Status Indicators (Compact) */}
        <div className="flex items-center gap-4 px-2 border-r border-slate-100 hidden xl:flex">
          <div className="flex flex-col items-center">
            <span className="text-[9px] font-black text-slate-400 uppercase leading-none mb-1">Total</span>
            <span className="text-lg font-black text-slate-900 leading-none">{stats.total}</span>
          </div>
          <div className="flex flex-col items-center">
            <span className="text-[9px] font-black text-green-500 uppercase leading-none mb-1">Active</span>
            <span className="text-lg font-black text-green-600 leading-none">{stats.active}</span>
          </div>
          <div className="flex flex-col items-center">
            <span className="text-[9px] font-black text-amber-500 uppercase leading-none mb-1">Case</span>
            <span className="text-lg font-black text-amber-600 leading-none">{stats.caseStudy}</span>
          </div>
          <div className="flex flex-col items-center">
            <span className="text-[9px] font-black text-red-400 uppercase leading-none mb-1">Inact</span>
            <span className="text-lg font-black text-red-500 leading-none">{stats.inactive}</span>
          </div>
        </div>

        {/* Unified Search */}
        <div className="relative flex-1 group min-w-[180px] w-full lg:w-auto">
          <input type="text" placeholder="Search entity..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-2.5 pl-10 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 transition-all outline-none" />
          <svg className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        {/* Jurisdiction Filter */}
        <select value={jurisdictionFilter} onChange={e => handleJurisdictionChange(e.target.value)}
          className="bg-slate-50 border-none rounded-xl px-4 py-2.5 text-[11px] font-black uppercase tracking-widest text-slate-600 focus:ring-2 focus:ring-indigo-600/10 outline-none w-full lg:w-auto">
          <option value="All">Jurisdiction: All</option>
          <option value="State">State</option>
          <option value="Center">Center</option>
        </select>

        {/* Secondary Filter: Sector or Range */}
        {jurisdictionFilter === 'State' && (
          <select value={sectorFilter} onChange={e => setSectorFilter(e.target.value)}
            className="bg-slate-50 border-none rounded-xl px-4 py-2.5 text-[11px] font-black uppercase tracking-widest text-slate-600 focus:ring-2 focus:ring-indigo-600/10 outline-none w-full lg:w-auto animate-in fade-in slide-in-from-left-2 duration-300">
            <option value="All">All Sectors</option>
            {sectors.map(s => <option key={s} value={s}>{s}</option>)}
          </select>
        )}

        {jurisdictionFilter === 'Center' && (
          <select value={rangeFilter} onChange={e => setRangeFilter(e.target.value)}
            className="bg-slate-50 border-none rounded-xl px-4 py-2.5 text-[11px] font-black uppercase tracking-widest text-slate-600 focus:ring-2 focus:ring-indigo-600/10 outline-none w-full lg:w-auto animate-in fade-in slide-in-from-left-2 duration-300">
            <option value="All">All Ranges</option>
            {ranges.map(r => <option key={r} value={r}>{r}</option>)}
          </select>
        )}

        {/* Combined Data Icon (Import/Export) */}
        <div className="relative shrink-0">
          <button onClick={() => setShowDataOptions(!showDataOptions)} className="h-10 w-10 flex items-center justify-center bg-slate-100 rounded-xl text-slate-600 hover:bg-indigo-600 hover:text-white transition-all shadow-sm">
             <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 7v10c0 2 1 3 3 3h10c2 0 3-1 3-3V7c0-2-1-3-3-3H7C5 4 4 5 4 7zm4 4h8m-8 4h5" /></svg>
          </button>
          {showDataOptions && (
            <div className="absolute right-0 mt-2 w-52 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 p-2 overflow-hidden animate-in zoom-in-95">
              <button onClick={handleImportTemplateCSV} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-600 hover:bg-slate-50 rounded-xl">CSV Template</button>
              <label className="w-full block px-4 py-3 text-[10px] font-black uppercase tracking-widest text-indigo-600 hover:bg-slate-50 rounded-xl cursor-pointer">
                Upload CSV <input type="file" accept=".csv" className="hidden" onChange={handleFileUpload} />
              </label>
              <button onClick={handleExportCSV} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-600 hover:bg-slate-50 rounded-xl border-t border-slate-50 mt-1">Export Data</button>
            </div>
          )}
        </div>

        {/* Add Client Button */}
        <button onClick={() => setIsModalOpen(true)} className="bg-indigo-600 text-white font-black uppercase tracking-tight px-4 h-10 rounded-xl shadow-lg hover:bg-slate-900 transition-all flex items-center gap-2 shrink-0 text-base whitespace-nowrap">
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
          Add Client
        </button>
      </div>

      <div className="flex-1 min-h-0 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <MasterPortfolio 
          key={refreshTrigger} 
          filter="gst" 
          externalSearch={search} 
          hideInternalSearch={true} 
          jurisdictionFilter={jurisdictionFilter}
          sectorFilter={sectorFilter}
          rangeFilter={rangeFilter}
        />
      </div>

      <GSTClientFormModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={() => setRefreshTrigger(p => p + 1)} />
    </div>
  );
};

export default GSTPortfolio;

import React, { useState, useEffect, useMemo } from 'react';
import { Client, JurisdictionType } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import GSTClientFormModal from '../Clientform/GSTClientFormModal';
import ITClientFormModal from '../Clientform/ITClientFormModal';
import Loader from '../../components/Loader';

interface MasterPortfolioProps {
  filter?: 'gst' | 'it';
  externalSearch?: string;
  hideInternalSearch?: boolean;
  jurisdictionFilter?: JurisdictionType | 'All';
  sectorFilter?: string;
  rangeFilter?: string;
}

const MasterPortfolio: React.FC<MasterPortfolioProps> = ({ 
  filter, 
  externalSearch = '', 
  hideInternalSearch = false,
  jurisdictionFilter = 'All',
  sectorFilter = 'All',
  rangeFilter = 'All'
}) => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [isGstModalOpen, setIsGstModalOpen] = useState(false);
  const [isItModalOpen, setIsItModalOpen] = useState(false);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      setClients(data || []);
    } catch (error) {
      console.error("Failed to fetch clients", error);
      setClients([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
  }, []);

  const filteredClients = useMemo(() => {
    let list = Array.isArray(clients) ? clients : [];

    if (filter === 'gst') {
      list = list.filter(c => !!c.gstProfile);
      if (jurisdictionFilter !== 'All') {
        list = list.filter(c => c.gstProfile?.jurisdictionType === jurisdictionFilter);

        // Apply sector filter if jurisdiction is State
        if (jurisdictionFilter === 'State' && sectorFilter !== 'All') {
          list = list.filter(c => c.gstProfile?.sector === sectorFilter);
        }

        // Apply range filter if jurisdiction is Center
        if (jurisdictionFilter === 'Center' && rangeFilter !== 'All') {
          list = list.filter(c => c.gstProfile?.range === rangeFilter);
        }
      }
    } else if (filter === 'it') {
      list = list.filter(c => !!c.itProfile);
    }

    const s = (externalSearch || search || '').toLowerCase();
    return list.filter(c => 
      (c.legalName || '').toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) || 
      (c.gstProfile?.gstin && c.gstProfile.gstin.toLowerCase().includes(s)) || 
      (c.mobile || '').includes(s)
    );
  }, [clients, search, externalSearch, filter, jurisdictionFilter, sectorFilter, rangeFilter]);

  const handleEdit = (client: Client) => {
    setSelectedClient(client);
    if (client.gstProfile) {
      setIsGstModalOpen(true);
    } else {
      setIsItModalOpen(true);
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm('Are you sure you want to delete this client record?')) {
      await mockBackend.deleteClient(id);
      fetchClients();
    }
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full animate-in fade-in slide-in-from-bottom-4 duration-500">
      {!hideInternalSearch && !externalSearch && (
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-4 shrink-0">
          <div className="relative flex-1 max-w-xl group">
            <input 
              type="text" 
              placeholder="Search legal name or identifier..."
              className="w-full bg-white border border-slate-200 rounded-2xl py-4 pl-12 pr-6 font-bold text-slate-900 shadow-sm focus:ring-4 focus:ring-indigo-50 transition-all outline-none"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
            <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </div>
        </div>
      )}

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse min-w-[900px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 bg-slate-50">Legal Entity</th>
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 bg-slate-50">Identifier (GSTIN)</th>
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 bg-slate-50">Jurisdiction</th>
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 bg-slate-50 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredClients.length === 0 ? (
                <tr>
                  <td colSpan={4} className="py-20 text-center text-slate-400 font-bold uppercase tracking-widest text-xs">No records found</td>
                </tr>
              ) : (
                filteredClients.map((client) => (
                  <tr key={client.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-8 py-6">
                      <p className="text-base font-black text-slate-900 leading-tight">{client.legalName}</p>
                      <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-tight">{client.tradeName || 'No Trade Name'}</p>
                    </td>
                    <td className="px-8 py-6">
                      {client.gstProfile && (
                        <div className="flex items-center gap-2">
                           <div className="h-5 w-5 rounded-md bg-blue-50 flex items-center justify-center text-blue-600 font-black text-[10px]">G</div>
                           <span className="text-[11px] font-bold text-slate-600 font-mono uppercase tracking-widest">{client.gstProfile.gstin}</span>
                        </div>
                      )}
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex flex-col">
                        <span className="px-2 py-0.5 rounded bg-slate-100 text-[9px] font-black text-slate-500 uppercase tracking-widest w-fit mb-1">
                          {client.gstProfile?.jurisdictionType || 'N/A'}
                        </span>
                        <span className="text-[10px] font-bold text-slate-400 uppercase">
                          {client.gstProfile?.jurisdictionType === 'State' ? client.gstProfile.sector : client.gstProfile?.range}
                        </span>
                      </div>
                    </td>
                    <td className="px-8 py-6 text-right">
                      <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => handleEdit(client)} className="h-9 w-9 rounded-xl bg-white border border-slate-200 text-slate-400 hover:text-indigo-600 hover:border-indigo-200 shadow-sm flex items-center justify-center">
                          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                        </button>
                        <button onClick={() => handleDelete(client.id)} className="h-9 w-9 rounded-xl bg-white border border-slate-200 text-slate-400 hover:text-red-600 hover:border-red-200 shadow-sm flex items-center justify-center">
                          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      <GSTClientFormModal isOpen={isGstModalOpen} onClose={() => setIsGstModalOpen(false)} onSave={() => fetchClients()} initialData={selectedClient} />
      <ITClientFormModal isOpen={isItModalOpen} onClose={() => setIsItModalOpen(false)} onSave={() => fetchClients()} initialData={selectedClient} />
    </div>
  );
};

export default MasterPortfolio;

