const Dashboard: React.FC = () => {
  const { user, token } = useAuth();
  const isOnline = useOffline();
  const { installPrompt, triggerInstall } = usePWA();
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDataLoading, setIsDataLoading] = useState(false);
  const [activeView, setActiveView] = useState<ActiveView>('dashboard');
  const [state, setState] = useState<AppState>({
    messages: [],
    metrics: INITIAL_METRICS as MetricData[],
    users: [],
    isConnected: false,
    currentUser: user,
  });

  const activeViewConfig = useMemo(() => VIEW_CONFIG[activeView] || { label: 'Clientify Suite', description: 'Professional Consultant Solution' }, [activeView]);

  // Load items data for metrics
  useEffect(() => {
    const loadData = async () => {
      setIsDataLoading(true);
      try {
        const items = await api.get('/items');
        setState(prev => ({
          ...prev,
          metrics: prev.metrics.map(m => 
            m.label === 'Active Clients' ? { ...m, value: items.length || 0, trend: items.length > 0 ? 'up' : 'stable' } : m
          )
        }));
      } catch (err) {
        console.error('Failed to load dashboard data', err);
      } finally {
        setIsDataLoading(false);
      }
    };
    if (isOnline && token) loadData();
  }, [isOnline, token]);

  useEffect(() => {
    if (isOnline) {
      socketService.connect();
      socketService.on('message', (msg: Message) => {
        setState(prev => ({ ...prev, messages: [...prev.messages, msg] }));
      });
      setState(prev => ({ ...prev, isConnected: true }));
    } else {
      socketService.disconnect();
      setState(prev => ({ ...prev, isConnected: false }));
    }
    return () => { socketService.disconnect(); };
  }, [isOnline]);

  const handleSendMessage = useCallback((content: string) => {
    const newMessage: Message = { id: `msg_${Date.now()}`, sender: user?.username || 'Consultant', content, timestamp: Date.now() };
    setState(prev => ({ ...prev, messages: [...prev.messages, newMessage] }));
    socketService.emit('message', newMessage);
  }, [user]);

  if (isDataLoading) return <Loader />;

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return (
          <div className="max-w-7xl mx-auto space-y-10 animate-in fade-in duration-500">
            {installPrompt && <InstallBanner onInstall={triggerInstall} />}
            <div className="grid grid-cols-1 gap-8 sm:grid-cols-2 lg:grid-cols-4">
              {state.metrics.map((m, i) => <MetricCard key={i} metric={m} />)}
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 rounded-[2.5rem] bg-white p-12 border border-slate-200 shadow-sm">
                <h3 className="text-2xl font-black text-slate-900 mb-2">Firm Performance</h3>
                <p className="text-slate-500 mb-10">Weekly compliance tracking summary</p>
                <div className="h-64 flex items-end justify-between gap-6">
                  {[40, 70, 45, 90, 65, 85, 30, 95, 50, 75].map((h, i) => (
                    <div key={i} className="flex-1 bg-indigo-50 rounded-2xl group relative hover:bg-indigo-100 cursor-pointer transition-colors">
                      <div className="absolute inset-x-0 bottom-0 bg-indigo-600 rounded-2xl transition-all duration-700" style={{ height: `${h}%` }} />
                    </div>
                  ))}
                </div>
              </div>
              <ChatPanel messages={state.messages} onSend={handleSendMessage} currentUser={user} />
            </div>
          </div>
        );

      case 'gst-portfolio': return <GSTPortfolio />;
      case 'it-portfolio': return <ITPortfolio />;
      case 'compliance-monthly': return <MonthlyFiling />;
      case 'compliance-quarterly': return <QuarterlyFiling />;
      case 'compliance-composition': return <CompositionFiling />;
      case 'compliance-gstr4': return <GSTR4 />;
      case 'compliance-gstr9': return <GSTR9_9C />;
      case 'compliance-itr': return <ITRReturn />;
      case 'compliance-taxaudit': return <TAXAudit />;
      case 'compliance-balancesheets': return <Balancesheet />;
      case 'lit-notice-pending': return <NoticePending />;
      case 'lit-notice-filed': return <NoticeFiled />;
      case 'lit-notice-drop': return <NoticeDrop />;
      case 'lit-notice-demand': return <NoticeDemand />;
      case 'lit-appeal-pending': return <AppealPending />;
      case 'lit-appeal-filed': return <AppealFiled />;
      case 'lit-appeal-drop': return <AppealDrop />;
      case 'lit-appeal-demand': return <AppealDemand />;
      case 'lit-tribunal-pending': return <TribunalPending />;
      case 'lit-tribunal-filed': return <TribunalFiled />;
      case 'lit-tribunal-drop': return <TribunalDrop />;
      case 'lit-tribunal-demand': return <TribunalDemand />;
      case 'lit-hc-pending': return <CourtPending />;
      case 'lit-hc-filed': return <CourtFiled />;
      case 'lit-hc-drop': return <CourtDrop />;
      case 'lit-hc-demand': return <CourtDemand />;
      case 'misc-gst-reg': return <GSTRegistration />;
      case 'misc-food-lic': return <FoodLicenses />;
      case 'misc-msme': return <MSMERegistration />;
      case 'misc-work': return <Miscellaneouswork />;
      case 'reminders': return <Reminders />;
      case 'messenger': return <Messenger />;
      case 'admin-invoices': return <Invoices />;
      case 'admin-payments': return <PaymentReceived />;
      case 'admin-duedates': return <DueDateSetting />;
      case 'settings': return <Setting />;
      case 'trash': return <Trash />;
      default: return <div className="p-20 text-center"><h2 className="text-2xl font-black">Module Not Ready</h2></div>;
    }
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-50">
      <Sidebar 
        activeView={activeView} 
        onViewChange={setActiveView} 
        isOpen={isSidebarOpen} 
        onClose={() => setIsSidebarOpen(false)} 
      />
      <main className="flex flex-1 flex-col overflow-hidden relative">
        <Header 
          isConnected={state.isConnected} 
          currentUser={user} 
          onMenuClick={() => setIsSidebarOpen(true)} 
          activeViewLabel={activeViewConfig.label}
          activeViewDescription={activeViewConfig.description}
        />
        <div className="flex-1 overflow-y-auto px-6 lg:px-12 pt-3 pb-6 lg:pb-12 no-scrollbar">
          <Suspense fallback={<Loader />}>{renderView()}</Suspense>
        </div>
      </main>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from 'react';
import MasterPortfolio from './MasterPortfolio';
import GSTClientFormModal from '../Clientform/GSTClientFormModal';
import { mockBackend } from '../../services/mockBackend';
import { Client, JurisdictionType, ClientStatus, GstStatus, GstRegType, GstFilingFreq, ConstitutionType } from '../../types';

const CSV_HEADERS = [
  "Legal Name", "Trade Name", "Mobile", "Email", "Client Status",
  "GSTIN", "Portal Username", "Portal Password", "GST Status", 
  "Reg Date", "Cancel Date", "Reg Type", "Filing Freq", 
  "Constitution", "Jurisdiction", "Sector", "Range", 
  "Address", "Bank Name", "Account No", "IFSC", "Remarks"
];

const GSTPortfolio: React.FC = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [search, setSearch] = useState('');
  const [jurisdictionFilter, setJurisdictionFilter] = useState<JurisdictionType | 'All'>('All');
  const [sectorFilter, setSectorFilter] = useState<string>('All');
  const [rangeFilter, setRangeFilter] = useState<string>('All');
  const [showDataOptions, setShowDataOptions] = useState(false);
  const [clients, setClients] = useState<Client[]>([]);

  useEffect(() => {
    const load = async () => {
      const data = await mockBackend.getClients();
      setClients(data.filter(c => !!c.gstProfile));
    };
    load();
  }, [refreshTrigger]);

  const stats = useMemo(() => {
    const total = clients.length;
    const active = clients.filter(c => c.status === 'Active Filing').length;
    const caseStudy = clients.filter(c => c.status === 'Case-by-Case').length;
    const inactive = clients.filter(c => c.status.startsWith('Inactive')).length;
    return { total, active, caseStudy, inactive };
  }, [clients]);

  const sectors = useMemo(() => {
    const s = new Set<string>();
    clients.forEach(c => {
      if (c.gstProfile?.jurisdictionType === 'State' && c.gstProfile.sector) {
        s.add(c.gstProfile.sector);
      }
    });
    return Array.from(s).sort();
  }, [clients]);

  const ranges = useMemo(() => {
    const r = new Set<string>();
    clients.forEach(c => {
      if (c.gstProfile?.jurisdictionType === 'Center' && c.gstProfile.range) {
        r.add(c.gstProfile.range);
      }
    });
    return Array.from(r).sort();
  }, [clients]);

  const handleJurisdictionChange = (val: string) => {
    setJurisdictionFilter(val as any);
    setSectorFilter('All');
    setRangeFilter('All');
  };

  const handleExportCSV = () => {
    const rows = clients.map(c => [
      c.legalName,
      c.tradeName,
      c.mobile,
      c.email || "",
      c.status,
      c.gstProfile?.gstin,
      c.gstProfile?.username,
      c.gstProfile?.password || "",
      c.gstProfile?.gstStatus,
      c.gstProfile?.regDate,
      c.gstProfile?.cancelDate || "",
      c.gstProfile?.regType,
      c.gstProfile?.filingFreq,
      c.gstProfile?.constitution,
      c.gstProfile?.jurisdictionType,
      c.gstProfile?.sector || "",
      c.gstProfile?.range || "",
      `"${(c.gstProfile?.address || "").replace(/"/g, '""')}"`,
      c.bankDetails?.bankName || "",
      c.bankDetails?.accountNo || "",
      c.bankDetails?.ifsc || "",
      `"${(c.remarks || "").replace(/"/g, '""')}"`
    ]);
    const csvContent = [CSV_HEADERS, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `GST_Portfolio_Full_${new Date().toISOString().split('T')[0]}.csv`);
    link.click();
    setShowDataOptions(false);
  };

  const handleImportTemplateCSV = () => {
    const csvContent = [CSV_HEADERS].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "GST_Clientify_Template.csv");
    link.click();
    setShowDataOptions(false);
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (e) => {
      const text = e.target?.result as string;
      const rows = text.split('\n').slice(1);
      let successCount = 0;
      for (const row of rows) {
        if (!row.trim()) continue;
        const cols = row.split(',').map(c => c.trim().replace(/^"|"$/g, ''));
        if (cols.length < 6) continue; // Basic validation

        const gstin = cols[5];
        if (!gstin) continue;

        try {
          await mockBackend.saveClient({
            legalName: cols[0],
            tradeName: cols[1],
            mobile: cols[2],
            email: cols[3],
            status: (cols[4] as ClientStatus) || 'Active Filing',
            gstProfile: {
              gstin,
              username: cols[6] || '',
              password: cols[7] || '',
              gstStatus: (cols[8] as GstStatus) || 'Active',
              regDate: cols[9] || new Date().toISOString().split('T')[0],
              cancelDate: cols[10] || undefined,
              regType: (cols[11] as GstRegType) || 'Regular',
              filingFreq: (cols[12] as GstFilingFreq) || 'Monthly',
              constitution: (cols[13] as ConstitutionType) || 'Proprietorship',
              jurisdictionType: (cols[14] as JurisdictionType) || 'State',
              sector: cols[15],
              range: cols[16],
              address: cols[17],
              stakeholders: []
            },
            bankDetails: {
              bankName: cols[18] || '',
              accountNo: cols[19] || '',
              ifsc: cols[20] || ''
            },
            remarks: cols[21]
          });
          successCount++;
        } catch (err) {
          console.error("Import Row Error:", err);
        }
      }
      alert(`Import complete: ${successCount} clients updated/added.`);
      setRefreshTrigger(p => p + 1);
      setShowDataOptions(false);
    };
    reader.readAsText(file);
    event.target.value = ''; // Reset input
  };

  return (
    <div className="flex flex-col h-full space-y-3 pb-4 overflow-hidden">
      {/* Consolidated Toolbar */}
      <div className="flex flex-col lg:flex-row items-center gap-3 bg-white p-2.5 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">

        {/* Status Indicators (Compact) */}
        <div className="flex items-center gap-4 px-2 border-r border-slate-100 hidden xl:flex">
          <div className="flex flex-col items-center">
            <span className="text-[9px] font-black text-slate-400 uppercase leading-none mb-1">Total</span>
            <span className="text-lg font-black text-slate-900 leading-none">{stats.total}</span>
          </div>
          <div className="flex flex-col items-center">
            <span className="text-[9px] font-black text-green-500 uppercase leading-none mb-1">Active</span>
            <span className="text-lg font-black text-green-600 leading-none">{stats.active}</span>
          </div>
          <div className="flex flex-col items-center">
            <span className="text-[9px] font-black text-amber-500 uppercase leading-none mb-1">Case</span>
            <span className="text-lg font-black text-amber-600 leading-none">{stats.caseStudy}</span>
          </div>
          <div className="flex flex-col items-center">
            <span className="text-[9px] font-black text-red-400 uppercase leading-none mb-1">Inact</span>
            <span className="text-lg font-black text-red-500 leading-none">{stats.inactive}</span>
          </div>
        </div>

        {/* Unified Search */}
        <div className="relative flex-1 group min-w-[180px] w-full lg:w-auto">
          <input type="text" placeholder="Search legal name or GSTIN..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-2.5 pl-10 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 transition-all outline-none" />
          <svg className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        {/* Jurisdiction Filter */}
        <select value={jurisdictionFilter} onChange={e => handleJurisdictionChange(e.target.value)}
          className="bg-slate-50 border-none rounded-xl px-4 py-2.5 text-[11px] font-black uppercase tracking-widest text-slate-600 focus:ring-2 focus:ring-indigo-600/10 outline-none w-full lg:w-auto">
          <option value="All">Jurisdiction: All</option>
          <option value="State">State</option>
          <option value="Center">Center</option>
        </select>

        {/* Secondary Filter: Sector or Range */}
        {jurisdictionFilter === 'State' && (
          <select value={sectorFilter} onChange={e => setSectorFilter(e.target.value)}
            className="bg-slate-50 border-none rounded-xl px-4 py-2.5 text-[11px] font-black uppercase tracking-widest text-slate-600 focus:ring-2 focus:ring-indigo-600/10 outline-none w-full lg:w-auto animate-in fade-in slide-in-from-left-2 duration-300">
            <option value="All">All Sectors</option>
            {sectors.map(s => <option key={s} value={s}>{s}</option>)}
          </select>
        )}

        {jurisdictionFilter === 'Center' && (
          <select value={rangeFilter} onChange={e => setRangeFilter(e.target.value)}
            className="bg-slate-50 border-none rounded-xl px-4 py-2.5 text-[11px] font-black uppercase tracking-widest text-slate-600 focus:ring-2 focus:ring-indigo-600/10 outline-none w-full lg:w-auto animate-in fade-in slide-in-from-left-2 duration-300">
            <option value="All">All Ranges</option>
            {ranges.map(r => <option key={r} value={r}>{r}</option>)}
          </select>
        )}

        {/* Combined Data Icon (Import/Export) */}
        <div className="relative shrink-0">
          <button onClick={() => setShowDataOptions(!showDataOptions)} className="h-10 w-10 flex items-center justify-center bg-slate-100 rounded-xl text-slate-600 hover:bg-indigo-600 hover:text-white transition-all shadow-sm">
             <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 7v10c0 2 1 3 3 3h10c2 0 3-1 3-3V7c0-2-1-3-3-3H7C5 4 4 5 4 7zm4 4h8m-8 4h5" /></svg>
          </button>
          {showDataOptions && (
            <div className="absolute right-0 mt-2 w-56 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 p-2 overflow-hidden animate-in zoom-in-95">
              <button onClick={handleImportTemplateCSV} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-600 hover:bg-slate-50 rounded-xl">Download Template</button>
              <label className="w-full block px-4 py-3 text-[10px] font-black uppercase tracking-widest text-indigo-600 hover:bg-slate-50 rounded-xl cursor-pointer">
                Bulk Import CSV <input type="file" accept=".csv" className="hidden" onChange={handleFileUpload} />
              </label>
              <button onClick={handleExportCSV} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-600 hover:bg-slate-50 rounded-xl border-t border-slate-50 mt-1">Export All Data</button>
            </div>
          )}
        </div>

        {/* Add Client Button */}
        <button onClick={() => setIsModalOpen(true)} className="bg-indigo-600 text-white font-black uppercase tracking-tight px-4 h-10 rounded-xl shadow-lg hover:bg-slate-900 transition-all flex items-center gap-2 shrink-0 text-base whitespace-nowrap">
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
          Add Client
        </button>
      </div>

      <div className="flex-1 min-h-0 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <MasterPortfolio 
          key={refreshTrigger} 
          filter="gst" 
          externalSearch={search} 
          hideInternalSearch={true} 
          jurisdictionFilter={jurisdictionFilter}
          sectorFilter={sectorFilter}
          rangeFilter={rangeFilter}
        />
      </div>

      <GSTClientFormModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={() => setRefreshTrigger(p => p + 1)} />
    </div>
  );
};

export default GSTPortfolio;

export interface Message {
  id: string;
  sender: string;
  content: string;
  timestamp: number;
}

export interface MetricData {
  label: string;
  value: number;
  trend: 'up' | 'down' | 'stable';
}

export interface User {
  id: string;
  username: string;
  user_id: string;
  email_id: string;
  mobile_no?: string;
  firm_name?: string | null;
  gstn?: string | null;
  status: 'online' | 'away' | 'offline';
}

export interface AppState {
  messages: Message[];
  metrics: MetricData[];
  users: User[];
  isConnected: boolean;
  currentUser: User | null;
}

export type ActiveView = string;

export type ClientStatus = 'Active Filing' | 'Case-by-Case' | 'Inactive (Temporary)' | 'Inactive (Closed)';
export type GstStatus = 'Active' | 'Suspended' | 'Cancelled';
export type GstRegType = 'Regular' | 'Composition';
export type GstFilingFreq = 'Monthly' | 'Quarterly';
export type ConstitutionType = 'Proprietorship' | 'Partnership' | 'HUF' | 'Company' | 'Trust' | 'Other';
export type JurisdictionType = 'Center' | 'State';
export type ClientService = 'IT Return' | 'Audit' | 'Notice handling' | 'MSME' | 'Food License';

export interface Stakeholder {
  id: string;
  name: string;
  mobile: string;
  pan: string;
}

export interface GSTProfile {
  gstin: string;
  username: string;
  password?: string;
  gstStatus: GstStatus;
  regDate: string;
  cancelDate?: string;
  regType: GstRegType;
  filingFreq: GstFilingFreq;
  constitution: ConstitutionType;
  stakeholders: Stakeholder[];
  accountantName?: string;
  accountantMobile?: string;
  certificateUrl?: string;
  address?: string;
  jurisdictionType?: JurisdictionType;
  sector?: string;
  range?: string;
}

export interface ITProfile {
  pan: string;
  category: string;
  username: string;
  password?: string;
}

export interface BankDetails {
  bankName: string;
  accountNo: string;
  ifsc: string;
}

export interface Client {
