    setIsLoading(true);
    const [recs, clis] = await Promise.all([
      mockBackend.getLitigationRecords(),
      mockBackend.getClients()
    ]);
    setRecords(recs.filter(r => r.category === category && r.status === status));
    setClients(clis);
    setIsLoading(false);
  };

  useEffect(() => {
    fetchAll();
  }, [category, status]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedRecord?.clientId || !selectedRecord?.referenceNo) return;

    const client = clients.find(c => c.id === selectedRecord.clientId);
    await mockBackend.saveLitigationRecord({
      ...selectedRecord,
      clientName: client?.legalName || 'Unknown',
      category,
      status
    });
    setIsModalOpen(false);
    fetchAll();
  };

  if (isLoading) return <Loader />;

  const statusColors = {
    Pending: 'bg-amber-100 text-amber-700',
    Filed: 'bg-indigo-100 text-indigo-700',
    Drop: 'bg-green-100 text-green-700',
    Demand: 'bg-red-100 text-red-700'
  };

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 h-full flex flex-col">
      <div className="flex items-center justify-between mb-6 shrink-0">
        <div>
           <h2 className="text-2xl font-black text-slate-900">{category} Suite: {status}</h2>
           <p className="text-slate-500 font-medium">Tracking legal proceedings and compliance history.</p>
        </div>
        <button onClick={() => { setSelectedRecord({ status, category }); setIsModalOpen(true); }}
          className="bg-indigo-600 text-white font-black uppercase tracking-widest px-6 py-3 rounded-xl shadow-lg hover:bg-slate-900 transition-all text-xs flex items-center gap-2">
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
          Record {category}
        </button>
      </div>

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse min-w-[1000px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400">Entity / Reference</th>
                <th className="px-8 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400">Section / Officer</th>
                <th className="px-8 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400">Timelines</th>
                <th className="px-8 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400">Amount / Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {records.length === 0 ? (
                <tr><td colSpan={4} className="py-20 text-center text-slate-400 font-black uppercase tracking-widest text-xs">No records tracked</td></tr>
              ) : (
                records.map(rec => (
                  <tr key={rec.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-8 py-6">
                      <p className="text-base font-black text-slate-900">{rec.clientName}</p>
                      <p className="text-xs font-bold text-slate-400 uppercase tracking-tight">{rec.referenceNo}</p>
                    </td>
                    <td className="px-8 py-6">
                       <p className="text-sm font-bold text-slate-600">{rec.section || 'N/A'}</p>
                       <p className="text-xs font-medium text-slate-400">{rec.officerName || 'Unknown Officer'}</p>
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex flex-col gap-1">
                        <span className="text-[10px] font-black text-slate-400 uppercase">Issued: {rec.issuedDate}</span>
                        <span className="text-[10px] font-black text-red-500 uppercase">Due: {rec.dueDate}</span>
                        {rec.filedDate && <span className="text-[10px] font-black text-indigo-600 uppercase">Filed: {rec.filedDate}</span>}
                      </div>
                    </td>
                    <td className="px-8 py-6">
                       <p className="text-sm font-black text-slate-900">₹{rec.amountInvolved?.toLocaleString() || '0'}</p>
                       <span className={`px-2 py-0.5 rounded text-[9px] font-black uppercase tracking-widest ${statusColors[rec.status]}`}>{rec.status}</span>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/40 backdrop-blur-md p-4">
          <form onSubmit={handleSave} className="w-full max-w-lg bg-white rounded-[2.5rem] shadow-2xl p-8 space-y-6">
            <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">Record {category} Details</h3>

            <div className="space-y-4">
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Target Client</label>
                <select className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none"
                  value={selectedRecord?.clientId || ''} onChange={e => setSelectedRecord({...selectedRecord, clientId: e.target.value})}>
                  <option value="">Select Entity</option>
                  {clients.map(c => <option key={c.id} value={c.id}>{c.legalName}</option>)}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Ref No (SCN/APL)</label>
                  <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none uppercase"
                    value={selectedRecord?.referenceNo || ''} onChange={e => setSelectedRecord({...selectedRecord, referenceNo: e.target.value})} />
                </div>
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Section Ref</label>
                  <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none"
                    value={selectedRecord?.section || ''} onChange={e => setSelectedRecord({...selectedRecord, section: e.target.value})} placeholder="e.g. Sec 73" />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Issued Date</label>
                  <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none"
                    value={selectedRecord?.issuedDate || ''} onChange={e => setSelectedRecord({...selectedRecord, issuedDate: e.target.value})} />
                </div>
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Due Date</label>
                  <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none"
                    value={selectedRecord?.dueDate || ''} onChange={e => setSelectedRecord({...selectedRecord, dueDate: e.target.value})} />
                </div>
              </div>

              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Amount Involved (₹)</label>
                <input type="number" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none"
                  value={selectedRecord?.amountInvolved || ''} onChange={e => setSelectedRecord({...selectedRecord, amountInvolved: Number(e.target.value)})} />
              </div>
            </div>

            <div className="flex gap-4 pt-4">
              <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-4 text-slate-500 font-black uppercase tracking-widest text-[10px] border border-slate-100 rounded-xl">Cancel</button>
              <button type="submit" className="flex-[2] bg-indigo-600 text-white font-black uppercase tracking-widest text-[10px] py-4 rounded-xl shadow-xl hover:bg-slate-900 transition-all">Save {category} Record</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

