            <>
              <span className="flex-1 text-left font-bold text-sm truncate">{item.label}</span>
              {hasChildren && (
                <svg xmlns="http://www.w3.org/2000/svg" className={`h-3 w-3 transition-transform ${isExpanded ? 'rotate-90' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" />
                </svg>
              )}
            </>
          )}

          {!isOpen && isActive && !hasChildren && (
            <div className="absolute left-0 top-1/2 -translate-y-1/2 w-1 h-6 bg-indigo-600 rounded-r-full" />
          )}
        </button>

        {/* Hover Flyout for Collapsed State */}
        {!isOpen && hasChildren && isHovered && (
          <div className="fixed left-20 top-auto w-56 bg-white border border-slate-200 rounded-2xl shadow-2xl py-3 z-[999] animate-in slide-in-from-left-2 fade-in duration-200">
            <div className="px-5 py-2 mb-2 border-b border-slate-50">
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{item.label}</span>
            </div>
            {item.children?.map(child => (
              <button
                key={child.id}
                onClick={() => onViewChange(child.id as ActiveView)}
                className={`flex w-full items-center px-5 py-2.5 text-xs font-bold transition-all ${
                  activeView === child.id ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:text-indigo-600 hover:bg-slate-50'
                }`}
              >
                {child.label}
              </button>
            ))}
          </div>
        )}

        {/* Normal Expanded Nested List */}
        {isOpen && hasChildren && isExpanded && (
          <div className="mt-1 space-y-1 border-l-2 border-slate-100 ml-7 pl-2">
            {item.children?.map(child => (
              <button
                key={child.id}
                onClick={() => onViewChange(child.id as ActiveView)}
                className={`flex w-full items-center px-4 py-2 text-xs font-bold rounded-xl transition-all ${
                  activeView === child.id ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-50'
                }`}
              >
                {child.label}
              </button>
            ))}
          </div>
        )}
      </div>
    );
  };

  return (
    <aside 
      className={`fixed inset-y-0 left-0 z-50 flex flex-col border-r border-slate-200 bg-white transition-all duration-500 ease-in-out ${
        isOpen ? 'w-80 shadow-2xl shadow-slate-200' : 'w-20'
      }`}
    >
      <div className={`flex h-20 items-center border-b border-slate-50 shrink-0 overflow-hidden ${isOpen ? 'px-6' : 'justify-center'}`}>
        <div className="flex items-center gap-3">
          <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-indigo-600 text-white shadow-lg">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
          {isOpen && (
            <span className="text-2xl font-black text-slate-900 tracking-tight animate-in fade-in duration-500">
              Client<span className="text-indigo-600">ify</span>
            </span>
          )}
        </div>
      </div>

      <nav className="flex-1 overflow-y-auto overflow-x-hidden p-4 space-y-8 no-scrollbar">
        {navigation.map((group, i) => (
          <div key={i} className="space-y-3">
            {isOpen && (
              <h5 className="px-4 text-[10px] font-black uppercase tracking-[0.2em] text-slate-300">
                {group.group}
              </h5>
            )}
            <div className="space-y-1">
              {group.items.map(item => renderItem(item))}
            </div>
            {!isOpen && i < navigation.length - 1 && <div className="h-px bg-slate-100 mx-2" />}
          </div>
        ))}
      </nav>

      <div className="p-4 border-t border-slate-50 bg-slate-50/30">
        <button 
          onClick={onToggle}
          className={`flex w-full items-center gap-4 rounded-xl py-3 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all ${!isOpen ? 'justify-center' : 'px-4'}`}
        >
          <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 transition-transform duration-500 ${isOpen ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 5l7 7-7 7M5 5l7 7-7 7" />
          </svg>
          {isOpen && <span className="font-black text-xs uppercase tracking-widest">Collapse</span>}
        </button>

        <button 
          onClick={logout} 
          className={`flex w-full items-center gap-4 rounded-xl py-3 text-red-400 hover:bg-red-50 transition-all mt-2 ${!isOpen ? 'justify-center' : 'px-4'}`}
          title="Logout"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
          </svg>
          {isOpen && <span className="font-black text-xs uppercase tracking-widest">Sign Out</span>}
        </button>
      </div>
    </aside>
  );
};

