                      </td>
                      <td className="px-6 py-5">
                        <span className={`px-2.5 py-1 rounded-full text-[9px] font-black uppercase tracking-wider ${
                          client.status === 'Active Filing' ? 'bg-blue-100 text-blue-700' : 
                          client.status === 'Case-by-Case' ? 'bg-purple-100 text-purple-700' : 'bg-slate-100 text-slate-600'
                        }`}>
                          {client.status}
                        </span>
                      </td>
                      <td className="px-6 py-5 text-right">
