            </div>
            {!isOpen && i < navigation.length - 1 && <div className="h-px bg-slate-100 mx-2" />}
          </div>
        ))}
      </nav>

      <div className="p-4 border-t border-slate-50 space-y-2">
        <button onClick={onToggle} className={`flex w-full items-center gap-4 rounded-xl py-3 text-slate-400 hover:text-indigo-600 hover:bg-slate-50 transition-all ${!isOpen ? 'justify-center' : 'px-4'}`}>
          <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 transition-transform duration-500 ${isOpen ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 5l7 7-7 7M5 5l7 7-7 7" />
          </svg>
          {isOpen && <span className="font-black text-xs uppercase tracking-widest">Collapse</span>}
        </button>
        <button onClick={logout} className={`flex w-full items-center gap-4 rounded-xl py-3 text-red-400 hover:bg-red-50 transition-all ${!isOpen ? 'justify-center' : 'px-4'}`}>
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
          </svg>
          {isOpen && <span className="font-black text-xs uppercase tracking-widest">Sign Out</span>}
        </button>
      </div>
    </aside>
  );
};

