                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <ITClientFormModal isOpen={isItModalOpen} onClose={() => setIsItModalOpen(false)} onSave={() => fetchClients()} initialData={selectedClient} />
    </div>
  );
};

