import React, { useState, useEffect, useMemo } from 'react';
import { Client, JurisdictionType } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import GSTClientFormModal from '../Clientform/GSTClientFormModal';
import ITClientFormModal from '../Clientform/ITClientFormModal';
import Loader from '../../components/Loader';

interface MasterPortfolioProps {
  filter?: 'gst' | 'it';
  externalSearch?: string;
  hideInternalSearch?: boolean;
  jurisdictionFilter?: JurisdictionType | 'All';
  sectorFilter?: string;
  rangeFilter?: string;
}

const MasterPortfolio: React.FC<MasterPortfolioProps> = ({ 
  filter, 
  externalSearch = '', 
  hideInternalSearch = false,
  jurisdictionFilter = 'All',
  sectorFilter = 'All',
  rangeFilter = 'All'
}) => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [isGstModalOpen, setIsGstModalOpen] = useState(false);
  const [isItModalOpen, setIsItModalOpen] = useState(false);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);

  // Local column filters
  const [gstStatusColFilter, setGstStatusColFilter] = useState<string>('All');
  const [clientStatusColFilter, setClientStatusColFilter] = useState<string>('All');

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      setClients(data || []);
    } catch (error) {
      console.error("Failed to fetch clients", error);
      setClients([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
  }, []);

  const filteredClients = useMemo(() => {
    let list = Array.isArray(clients) ? clients : [];

    if (filter === 'gst') {
      list = list.filter(c => !!c.gstProfile);

      // External Global Filters
      if (jurisdictionFilter !== 'All') {
        list = list.filter(c => c.gstProfile?.jurisdictionType === jurisdictionFilter);
        if (jurisdictionFilter === 'State' && sectorFilter !== 'All') {
          list = list.filter(c => c.gstProfile?.sector === sectorFilter);
        }
        if (jurisdictionFilter === 'Center' && rangeFilter !== 'All') {
          list = list.filter(c => c.gstProfile?.range === rangeFilter);
        }
      }

      // Local Column Filters
      if (gstStatusColFilter !== 'All') {
        list = list.filter(c => c.gstProfile?.gstStatus === gstStatusColFilter);
      }
      if (clientStatusColFilter !== 'All') {
        list = list.filter(c => c.status === clientStatusColFilter);
      }

    } else if (filter === 'it') {
      list = list.filter(c => !!c.itProfile);
    }

    const s = (externalSearch || search || '').toLowerCase();
    return list.filter(c => 
      (c.legalName || '').toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) || 
      (c.gstProfile?.gstin && c.gstProfile.gstin.toLowerCase().includes(s)) || 
      (c.mobile || '').includes(s)
    );
  }, [clients, search, externalSearch, filter, jurisdictionFilter, sectorFilter, rangeFilter, gstStatusColFilter, clientStatusColFilter]);

  const handleEdit = (client: Client) => {
    setSelectedClient(client);
    if (client.gstProfile) {
      setIsGstModalOpen(true);
    } else {
      setIsItModalOpen(true);
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm('Are you sure you want to delete this client record?')) {
      await mockBackend.deleteClient(id);
      fetchClients();
    }
  };

  const copyAndOpen = (text: string, url: string) => {
    navigator.clipboard.writeText(text);
    window.open(url, '_blank');
