  const [clientStatusColFilter, setClientStatusColFilter] = useState<string>('All');

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      setClients(data || []);
    } catch (error) {
      console.error("Failed to fetch clients", error);
      setClients([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
  }, []);

  const filteredClients = useMemo(() => {
    let list = Array.isArray(clients) ? clients : [];

    if (filter === 'gst') {
      list = list.filter(c => !!c.gstProfile);

      // External Global Filters
      if (jurisdictionFilter !== 'All') {
        list = list.filter(c => c.gstProfile?.jurisdictionType === jurisdictionFilter);
        if (jurisdictionFilter === 'State' && sectorFilter !== 'All') {
          list = list.filter(c => c.gstProfile?.sector === sectorFilter);
        }
        if (jurisdictionFilter === 'Center' && rangeFilter !== 'All') {
          list = list.filter(c => c.gstProfile?.range === rangeFilter);
        }
      }

      // Local Column Filters
      if (gstStatusColFilter !== 'All') {
        list = list.filter(c => c.gstProfile?.gstStatus === gstStatusColFilter);
      }
      if (clientStatusColFilter !== 'All') {
        list = list.filter(c => c.status === clientStatusColFilter);
      }

    } else if (filter === 'it') {
      list = list.filter(c => !!c.itProfile);
    }

    const s = (externalSearch || search || '').toLowerCase();
    return list.filter(c => 
      (c.legalName || '').toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) || 
      (c.gstProfile?.gstin && c.gstProfile.gstin.toLowerCase().includes(s)) || 
      (c.mobile || '').includes(s)
    );
  }, [clients, search, externalSearch, filter, jurisdictionFilter, sectorFilter, rangeFilter, gstStatusColFilter, clientStatusColFilter]);

  const handleEdit = (client: Client) => {
    setSelectedClient(client);
    if (client.gstProfile) {
      setIsGstModalOpen(true);
    } else {
      setIsItModalOpen(true);
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm('Are you sure you want to delete this client record?')) {
      await mockBackend.deleteClient(id);
      fetchClients();
    }
  };

  const copyAndOpen = (text: string, url: string) => {
    navigator.clipboard.writeText(text);
    window.open(url, '_blank');
  };

  if (isLoading) return <Loader />;

  if (filter === 'gst') {
    return (
      <div className="flex flex-col h-full animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
          <div className="overflow-x-auto no-scrollbar flex-1">
            <table className="w-full text-left border-collapse table-auto">
              <thead className="sticky top-0 z-20">
                <tr className="bg-slate-50 border-b border-slate-100">
                  <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap">S.No.</th>
                  <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Trade Name</th>
                  <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Legal Name</th>
                  <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap">Mobile No.</th>
                  <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap">GSTIN</th>

                  {/* Interactive GST Status Filter */}
                  <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap text-center relative group">
                    <div className="flex items-center justify-center gap-1 cursor-pointer">
                      <select 
                        value={gstStatusColFilter}
                        onChange={(e) => setGstStatusColFilter(e.target.value)}
                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-30"
                      >
                        <option value="All">All GST Status</option>
                        <option value="Active">Active Only</option>
                        <option value="Suspended">Suspended</option>
                        <option value="Cancelled">Cancelled</option>
                      </select>
                      <span className={`transition-colors z-10 ${gstStatusColFilter !== 'All' ? 'text-indigo-600' : 'text-slate-400 group-hover:text-indigo-600'}`}>
                        {gstStatusColFilter === 'All' ? 'GST Status' : gstStatusColFilter}
                      </span>
                      <svg className={`h-3 w-3 transition-colors z-10 pointer-events-none ${gstStatusColFilter !== 'All' ? 'text-indigo-600' : 'text-slate-300 group-hover:text-indigo-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" />
                      </svg>
                    </div>
                  </th>

                  {/* Interactive Client Status Filter */}
                  <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap text-center relative group">
                    <div className="flex items-center justify-center gap-1 cursor-pointer">
                      <select 
                        value={clientStatusColFilter}
                        onChange={(e) => setClientStatusColFilter(e.target.value)}
                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-30"
                      >
                        <option value="All">All Client Status</option>
                        <option value="Active Filing">Active Filing</option>
                        <option value="Case-by-Case">Case-by-Case</option>
                        <option value="Inactive (Temporary)">Inactive (Temp)</option>
                        <option value="Inactive (Closed)">Inactive (Closed)</option>
                      </select>
                      <span className={`transition-colors z-10 ${clientStatusColFilter !== 'All' ? 'text-indigo-600' : 'text-slate-400 group-hover:text-indigo-600'}`}>
                        {clientStatusColFilter === 'All' ? 'Client Status' : clientStatusColFilter}
                      </span>
                      <svg className={`h-3 w-3 transition-colors z-10 pointer-events-none ${clientStatusColFilter !== 'All' ? 'text-indigo-600' : 'text-slate-300 group-hover:text-indigo-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" />
                      </svg>
                    </div>
                  </th>
                  <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right min-w-[100px]">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredClients.length === 0 ? (
                  <tr>
                    <td colSpan={8} className="py-20 text-center text-slate-400 font-bold uppercase tracking-widest text-xs">No records found matching filters</td>
                  </tr>
                ) : (
                  filteredClients.map((client, idx) => (
                    <tr key={client.id} className="hover:bg-slate-50/50 transition-colors group">
                      <td className="px-4 py-5">
                        <span className="text-xs font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</span>
                      </td>
                      <td className="px-4 py-5">
                        <p className="text-sm font-black text-slate-900 leading-tight truncate max-w-[160px]" title={client.tradeName}>{client.tradeName || '---'}</p>
                      </td>
                      <td className="px-4 py-5">
                        <p className="text-xs font-bold text-slate-500 uppercase truncate max-w-[160px]" title={client.legalName}>{client.legalName}</p>
                      </td>
                      <td className="px-4 py-5 whitespace-nowrap">
                        <p className="text-xs font-black text-slate-700">{client.mobile || '---'}</p>
                      </td>
                      <td className="px-4 py-5 whitespace-nowrap">
                        <div className="flex items-center gap-2">
                           <span className="text-[11px] font-black text-indigo-600 font-mono tracking-widest">{client.gstProfile?.gstin}</span>
                           <button 
                             onClick={() => copyAndOpen(client.gstProfile?.gstin || '', 'https://services.gst.gov.in/services/searchtp')}
                             className="h-6 w-6 rounded-lg bg-indigo-50 text-indigo-600 flex items-center justify-center hover:bg-indigo-600 hover:text-white transition-all shadow-sm"
                             title="Search on GST Portal"
                           >
                             <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                           </button>
                        </div>
                      </td>
                      <td className="px-4 py-5 text-center whitespace-nowrap">
                        <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider ${
                          client.gstProfile?.gstStatus === 'Active' ? 'bg-green-100 text-green-700' : 
                          client.gstProfile?.gstStatus === 'Suspended' ? 'bg-amber-100 text-amber-700' : 'bg-red-100 text-red-700'
                        }`}>
                          {client.gstProfile?.gstStatus || 'N/A'}
                        </span>
                      </td>
                      <td className="px-4 py-5 text-center whitespace-nowrap">
                        <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider ${
                          client.status === 'Active Filing' ? 'bg-blue-100 text-blue-700' : 
                          client.status === 'Case-by-Case' ? 'bg-purple-100 text-purple-700' : 'bg-slate-100 text-slate-600'
                        }`}>
                          {client.status}
                        </span>
                      </td>
                      <td className="px-4 py-5 text-right whitespace-nowrap">
                        <div className="flex items-center justify-end gap-1.5">
                          <button onClick={() => handleEdit(client)} className="h-8 w-8 rounded-lg bg-white border border-slate-200 text-slate-400 hover:text-indigo-600 hover:border-indigo-200 shadow-sm flex items-center justify-center transition-all">
                            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                          </button>
                          <button onClick={() => handleDelete(client.id)} className="h-8 w-8 rounded-lg bg-white border border-slate-200 text-slate-400 hover:text-red-600 hover:border-red-200 shadow-sm flex items-center justify-center transition-all">
                            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
        <GSTClientFormModal isOpen={isGstModalOpen} onClose={() => setIsGstModalOpen(false)} onSave={() => fetchClients()} initialData={selectedClient} />
      </div>
    );
  }

  // Fallback IT layout
  return (
    <div className="flex flex-col h-full animate-in fade-in slide-in-from-bottom-4 duration-500">
      {!hideInternalSearch && !externalSearch && (
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-4 shrink-0">
          <div className="relative flex-1 max-w-xl group">
            <input 
              type="text" 
              placeholder="Search legal name or identifier..."
              className="w-full bg-white border border-slate-200 rounded-2xl py-4 pl-12 pr-6 font-bold text-slate-900 shadow-sm focus:ring-4 focus:ring-indigo-50 transition-all outline-none"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
            <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </div>
        </div>
      )}

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-auto">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 bg-slate-50">Legal Entity</th>
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 bg-slate-50 whitespace-nowrap">Identifier (PAN)</th>
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 bg-slate-50">Category</th>
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 bg-slate-50 text-right min-w-[100px]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredClients.length === 0 ? (
                <tr>
                  <td colSpan={4} className="py-20 text-center text-slate-400 font-bold uppercase tracking-widest text-xs">No records found</td>
                </tr>
              ) : (
                filteredClients.map((client) => (
                  <tr key={client.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-8 py-6">
                      <p className="text-base font-black text-slate-900 leading-tight truncate max-w-[200px]" title={client.legalName}>{client.legalName}</p>
                      <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-tight truncate max-w-[200px]">{client.tradeName || 'No Trade Name'}</p>
                    </td>
                    <td className="px-8 py-6 whitespace-nowrap">
                      {client.itProfile && (
                        <div className="flex items-center gap-2">
                           <div className="h-5 w-5 rounded-md bg-emerald-50 flex items-center justify-center text-emerald-600 font-black text-[10px]">P</div>
                           <span className="text-[11px] font-bold text-slate-600 font-mono uppercase tracking-widest">{client.itProfile.pan}</span>
                        </div>
                      )}
                    </td>
                    <td className="px-8 py-6">
                      <span className="px-2 py-0.5 rounded bg-slate-100 text-[9px] font-black text-slate-500 uppercase tracking-widest w-fit">
                        {client.itProfile?.category || 'N/A'}
                      </span>
                    </td>
                    <td className="px-8 py-6 text-right whitespace-nowrap">
                      <div className="flex items-center justify-end gap-2">
                        <button onClick={() => handleEdit(client)} className="h-9 w-9 rounded-xl bg-white border border-slate-200 text-slate-400 hover:text-indigo-600 hover:border-indigo-200 shadow-sm flex items-center justify-center transition-all">
                          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                        </button>
                        <button onClick={() => handleDelete(client.id)} className="h-9 w-9 rounded-xl bg-white border border-slate-200 text-slate-400 hover:text-red-600 hover:border-red-200 shadow-sm flex items-center justify-center transition-all">
                          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      <ITClientFormModal isOpen={isItModalOpen} onClose={() => setIsItModalOpen(false)} onSave={() => fetchClients()} initialData={selectedClient} />
    </div>
  );
};

export default MasterPortfolio;

import React, { useState, useEffect, useMemo } from 'react';
import MasterPortfolio from './MasterPortfolio';
import GSTClientFormModal from '../Clientform/GSTClientFormModal';
import { mockBackend } from '../../services/mockBackend';
import { Client, JurisdictionType, ClientStatus, GstStatus, GstRegType, GstFilingFreq, ConstitutionType } from '../../types';

const CSV_HEADERS = [
  "Legal Name", "Trade Name", "Mobile", "Email", "Client Status",
  "GSTIN", "Portal Username", "Portal Password", "GST Status", 
  "Reg Date", "Cancel Date", "Reg Type", "Filing Freq", 
  "Constitution", "Jurisdiction", "Sector", "Range", 
  "Address", "Bank Name", "Account No", "IFSC", "Remarks"
];

const GSTPortfolio: React.FC = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [search, setSearch] = useState('');
  const [jurisdictionFilter, setJurisdictionFilter] = useState<JurisdictionType | 'All'>('All');
  const [sectorFilter, setSectorFilter] = useState<string>('All');
  const [rangeFilter, setRangeFilter] = useState<string>('All');
  const [showDataOptions, setShowDataOptions] = useState(false);
  const [clients, setClients] = useState<Client[]>([]);

  useEffect(() => {
    const load = async () => {
      const data = await mockBackend.getClients();
      setClients(data.filter(c => !!c.gstProfile));
    };
    load();
  }, [refreshTrigger]);

  const stats = useMemo(() => {
    const total = clients.length;
    const active = clients.filter(c => c.status === 'Active Filing').length;
    const caseStudy = clients.filter(c => c.status === 'Case-by-Case').length;
    const inactive = clients.filter(c => c.status.startsWith('Inactive')).length;
    return { total, active, caseStudy, inactive };
  }, [clients]);

  const sectors = useMemo(() => {
    const s = new Set<string>();
    clients.forEach(c => {
      if (c.gstProfile?.jurisdictionType === 'State' && c.gstProfile.sector) {
        s.add(c.gstProfile.sector);
      }
    });
    return Array.from(s).sort();
  }, [clients]);

  const ranges = useMemo(() => {
    const r = new Set<string>();
    clients.forEach(c => {
      if (c.gstProfile?.jurisdictionType === 'Center' && c.gstProfile.range) {
        r.add(c.gstProfile.range);
      }
    });
    return Array.from(r).sort();
  }, [clients]);

  const handleJurisdictionChange = (val: string) => {
    setJurisdictionFilter(val as any);
    setSectorFilter('All');
    setRangeFilter('All');
  };

  const handleExportCSV = () => {
    const rows = clients.map(c => [
      c.legalName,
      c.tradeName,
      c.mobile,
      c.email || "",
      c.status,
      c.gstProfile?.gstin,
      c.gstProfile?.username,
      c.gstProfile?.password || "",
      c.gstProfile?.gstStatus,
      c.gstProfile?.regDate,
      c.gstProfile?.cancelDate || "",
      c.gstProfile?.regType,
      c.gstProfile?.filingFreq,
      c.gstProfile?.constitution,
      c.gstProfile?.jurisdictionType,
      c.gstProfile?.sector || "",
      c.gstProfile?.range || "",
      `"${(c.gstProfile?.address || "").replace(/"/g, '""')}"`,
      c.bankDetails?.bankName || "",
      c.bankDetails?.accountNo || "",
      c.bankDetails?.ifsc || "",
      `"${(c.remarks || "").replace(/"/g, '""')}"`
    ]);
    const csvContent = [CSV_HEADERS, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `GST_Portfolio_Full_${new Date().toISOString().split('T')[0]}.csv`);
    link.click();
    setShowDataOptions(false);
  };

  const handleImportTemplateCSV = () => {
    const csvContent = [CSV_HEADERS].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "GST_Clientify_Template.csv");
    link.click();
    setShowDataOptions(false);
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (e) => {
      const text = e.target?.result as string;
      const rows = text.split('\n').slice(1);
      const allClients = await mockBackend.getClients();
      let successCount = 0;

      for (const row of rows) {
        if (!row.trim()) continue;
        const cols = row.split(',').map(c => c.trim().replace(/^"|"$/g, ''));
        if (cols.length < 6) continue;

        const gstin = cols[5];
        if (!gstin) continue;

        // Find existing client to update if possible
        const existing = allClients.find(c => c.gstProfile?.gstin === gstin);

        try {
          await mockBackend.saveClient({
            id: existing?.id, // Passing ID will update the record instead of creating new
            legalName: cols[0],
            tradeName: cols[1],
            mobile: cols[2],
            email: cols[3],
            status: (cols[4] as ClientStatus) || 'Active Filing',
            gstProfile: {
              gstin,
              username: cols[6] || '',
              password: cols[7] || '',
              gstStatus: (cols[8] as GstStatus) || 'Active',
              regDate: cols[9] || new Date().toISOString().split('T')[0],
              cancelDate: cols[10] || undefined,
              regType: (cols[11] as GstRegType) || 'Regular',
              filingFreq: (cols[12] as GstFilingFreq) || 'Monthly',
              constitution: (cols[13] as ConstitutionType) || 'Proprietorship',
              jurisdictionType: (cols[14] as JurisdictionType) || 'State',
              sector: cols[15],
              range: cols[16],
              address: cols[17],
              stakeholders: existing?.gstProfile?.stakeholders || []
            },
            bankDetails: {
              bankName: cols[18] || '',
              accountNo: cols[19] || '',
              ifsc: cols[20] || ''
            },
            remarks: cols[21]
          });
          successCount++;
        } catch (err) {
          console.error("Import Row Error:", err);
        }
      }
      alert(`Import complete: ${successCount} clients processed (updated/added).`);
      setRefreshTrigger(p => p + 1);
      setShowDataOptions(false);
    };
    reader.readAsText(file);
    event.target.value = ''; // Reset input
  };

  return (
    <div className="flex flex-col h-full space-y-3 pb-4 overflow-hidden">
      {/* Consolidated Toolbar */}
      <div className="flex flex-col lg:flex-row items-center gap-3 bg-white p-2.5 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">

        {/* Status Indicators */}
        <div className="flex items-center gap-4 px-2 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="flex flex-col items-center min-w-[32px]">
            <span className="text-[9px] font-black text-slate-400 uppercase leading-none mb-1">Total</span>
            <span className="text-lg font-black text-slate-900 leading-none">{stats.total}</span>
          </div>
          <div className="flex flex-col items-center min-w-[32px]">
            <span className="text-[9px] font-black text-green-500 uppercase leading-none mb-1">Active</span>
            <span className="text-lg font-black text-green-600 leading-none">{stats.active}</span>
          </div>
          <div className="flex flex-col items-center min-w-[32px]">
            <span className="text-[9px] font-black text-amber-500 uppercase leading-none mb-1">Case</span>
            <span className="text-lg font-black text-amber-600 leading-none">{stats.caseStudy}</span>
          </div>
          <div className="flex flex-col items-center min-w-[32px]">
            <span className="text-[9px] font-black text-red-400 uppercase leading-none mb-1">Inact</span>
            <span className="text-lg font-black text-red-500 leading-none">{stats.inactive}</span>
