                  <p className="text-base font-black text-slate-700">{selectedClient.status}</p>
               </div>
               <div className="space-y-1">
                  <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Registration Type</p>
                  <p className="text-base font-black text-slate-700">{selectedClient.gstProfile?.regType} ({selectedClient.gstProfile?.filingFreq})</p>
               </div>
               <div className="col-span-2 space-y-1 pt-4 border-t border-slate-100">
                  <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Registered Address</p>
