               <button onClick={() => handleEdit(selectedClient)} className="flex-1 py-4 bg-white border border-slate-200 rounded-2xl font-black text-[11px] uppercase tracking-widest text-indigo-600 hover:border-indigo-600 transition-all flex items-center justify-center gap-2 shadow-sm">
                 <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                 Edit Client
               </button>
               <button onClick={() => handleDelete(selectedClient.id)} className="flex-1 py-4 bg-white border border-slate-200 rounded-2xl font-black text-[11px] uppercase tracking-widest text-red-600 hover:border-red-600 transition-all flex items-center justify-center gap-2 shadow-sm">
                 <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                 Delete Record
               </button>
            </div>
          </div>
        </div>
      )}

      {/* Login Portal Modal */}
      {isLoginModalOpen && selectedClient && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-slate-900/60 backdrop-blur-lg p-4 animate-in fade-in duration-200">
           <div className="w-full max-w-md bg-white rounded-[2.5rem] shadow-2xl p-8 flex flex-col space-y-6 animate-in zoom-in-95">
              <div className="flex items-center justify-between">
                 <div className="h-12 w-12 rounded-2xl bg-indigo-600 text-white flex items-center justify-center shadow-lg">
                    <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 7a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2V9a2 2 0 012-2m10 0V5a2 2 0 00-2-2H9a2 2 0 00-2 2v2m10 0h-10" /></svg>
                 </div>
                 <button onClick={() => setIsLoginModalOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-100">
                    <svg className="h-5 w-5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                 </button>
              </div>

              <div className="text-center space-y-2">
                 <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">Portal Gateway</h3>
                 <p className="text-sm font-bold text-slate-500 uppercase tracking-widest">{selectedClient.legalName}</p>
              </div>

              <div className="space-y-4 pt-4">
                 <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Portal Username</label>
                    <div className="flex gap-2">
                       <input readOnly value={selectedClient.gstProfile?.username} className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-black text-slate-800 outline-none" />
                       <button onClick={() => copyToClipboard(selectedClient.gstProfile?.username || '', 'Username')} className="px-4 bg-slate-50 border border-slate-200 rounded-xl text-slate-400 hover:text-indigo-600 hover:border-indigo-200 transition-all">
                          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
