                 <p className="text-sm font-bold text-slate-500 uppercase tracking-widest">{selectedClient.legalName}</p>
              </div>

              <div className="space-y-4 pt-4">
                 <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Portal Username</label>
                    <div className="flex gap-2">
                       <input readOnly value={selectedClient.gstProfile?.username} className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-black text-slate-800 outline-none" />
                       <button onClick={() => copyToClipboard(selectedClient.gstProfile?.username || '')} className="px-4 bg-slate-50 border border-slate-200 rounded-xl text-slate-400 hover:text-indigo-600 transition-all">
                          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
                       </button>
                    </div>
                 </div>

                 <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block ml-1">Portal Password</label>
                    <div className="relative group">
                       <input 
                         type={showPassInLogin ? "text" : "password"} 
                         value={tempPassword} 
                         onChange={(e) => setTempPassword(e.target.value)}
                         className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-black text-slate-800 pr-12 outline-none focus:ring-4 focus:ring-indigo-50 transition-all" 
                       />
                       <button 
                         onClick={() => setShowPassInLogin(!showPassInLogin)}
                         className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-indigo-600 transition-colors"
                       >
                         {showPassInLogin ? <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 12z" /></svg> : <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18" /></svg>}
                       </button>
                    </div>
                 </div>
              </div>

              <button 
                onClick={() => openPortalLogin(selectedClient)}
                className="w-full py-5 bg-indigo-600 text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl shadow-indigo-100 hover:bg-slate-900 transition-all active:scale-95 flex items-center justify-center gap-3"
              >
                <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                Copy ID & Launch Portal
              </button>
           </div>
        </div>
      )}
    </div>
  );
};

export default GstMasterPortfolio;

import React, { useState, useEffect, useMemo } from 'react';
import { Client, JurisdictionType } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import GSTClientFormModal from '../Clientform/GSTClientFormModal';
import Loader from '../../components/Loader';

interface GstMasterPortfolioProps {
  externalSearch?: string;
  hideInternalSearch?: boolean;
  jurisdictionFilter?: JurisdictionType | 'All';
  sectorFilter?: string;
  rangeFilter?: string;
}

const GstMasterPortfolio: React.FC<GstMasterPortfolioProps> = ({ 
  externalSearch = '', 
  hideInternalSearch = false,
  jurisdictionFilter = 'All',
  sectorFilter = 'All',
  rangeFilter = 'All'
}) => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');

  const [isGstModalOpen, setIsGstModalOpen] = useState(false);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);
  const [activeMenuId, setActiveMenuId] = useState<string | null>(null);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);

  const [tempPassword, setTempPassword] = useState('');
  const [showPassInLogin, setShowPassInLogin] = useState(false);

  const [gstStatusColFilter, setGstStatusColFilter] = useState<string>('All');
  const [clientStatusColFilter, setClientStatusColFilter] = useState<string>('All');

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      setClients(data.filter(c => !!c.gstProfile) || []);
    } catch (error) {
      console.error("Failed to fetch clients", error);
      setClients([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
  }, []);

  const filteredClients = useMemo(() => {
    let list = Array.isArray(clients) ? clients : [];

    if (jurisdictionFilter !== 'All') {
      list = list.filter(c => c.gstProfile?.jurisdictionType === jurisdictionFilter);
      if (jurisdictionFilter === 'State' && sectorFilter !== 'All') {
        list = list.filter(c => c.gstProfile?.sector === sectorFilter);
      }
      if (jurisdictionFilter === 'Center' && rangeFilter !== 'All') {
        list = list.filter(c => c.gstProfile?.range === rangeFilter);
      }
    }

    if (gstStatusColFilter !== 'All') {
      list = list.filter(c => c.gstProfile?.gstStatus === gstStatusColFilter);
    }
    if (clientStatusColFilter !== 'All') {
      list = list.filter(c => c.status === clientStatusColFilter);
    }

    const s = (externalSearch || search || '').toLowerCase();
    return list.filter(c => 
      (c.legalName || '').toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) || 
      (c.gstProfile?.gstin && c.gstProfile.gstin.toLowerCase().includes(s)) || 
      (c.mobile || '').includes(s)
    );
  }, [clients, search, externalSearch, jurisdictionFilter, sectorFilter, rangeFilter, gstStatusColFilter, clientStatusColFilter]);

  const handleEdit = (client: Client) => {
    setSelectedClient(client);
    setIsGstModalOpen(true);
    setIsDetailModalOpen(false);
  };

  const handleDelete = async (id: string) => {
    if (confirm('Are you sure you want to delete this client record?')) {
      await mockBackend.deleteClient(id);
      setIsDetailModalOpen(false);
      fetchClients();
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const handleShare = async (title: string, text: string, url?: string) => {
    if (navigator.share) {
      try {
        await navigator.share({ title, text, url });
      } catch (err) {
        console.warn('Sharing failed', err);
      }
    } else {
      copyToClipboard(`${text}${url ? `\nLink: ${url}` : ''}`);
      alert('Content copied to clipboard (Sharing not supported on this browser)');
    }
    setActiveMenuId(null);
  };

  const openPortalLogin = (client: Client) => {
    copyToClipboard(client.gstProfile?.username || '');
    window.open('https://services.gst.gov.in/services/login', '_blank');
  };

  const getCredText = (client: Client) => {
    return `GST Credentials for ${client.legalName}\n\nGSTIN: ${client.gstProfile?.gstin}\nUsername: ${client.gstProfile?.username}\nPassword: ${client.gstProfile?.password}\n\nShared via Clientify Vault`;
  };

  const getCertText = (client: Client) => {
    return `GST Registration Certificate - ${client.legalName}\nGSTIN: ${client.gstProfile?.gstin}`;
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-auto">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap">S.No.</th>
                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Trade Name</th>
                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Legal Name</th>
                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap">Mobile No.</th>
                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap">GSTIN</th>

                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap text-center relative group">
                  <div className="flex items-center justify-center gap-1 cursor-pointer">
                    <select value={gstStatusColFilter} onChange={(e) => setGstStatusColFilter(e.target.value)} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-30">
                      <option value="All">All GST Status</option>
                      <option value="Active">Active Only</option>
                      <option value="Suspended">Suspended</option>
                      <option value="Cancelled">Cancelled</option>
                    </select>
                    <span className={`transition-colors z-10 ${gstStatusColFilter !== 'All' ? 'text-indigo-600' : 'text-slate-400 group-hover:text-indigo-600'}`}>
                      {gstStatusColFilter === 'All' ? 'GST Status' : gstStatusColFilter}
                    </span>
                    <svg className={`h-3 w-3 transition-colors z-10 pointer-events-none ${gstStatusColFilter !== 'All' ? 'text-indigo-600' : 'text-slate-300 group-hover:text-indigo-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" />
                    </svg>
                  </div>
                </th>

                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap text-center relative group">
                  <div className="flex items-center justify-center gap-1 cursor-pointer">
                    <select value={clientStatusColFilter} onChange={(e) => setClientStatusColFilter(e.target.value)} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-30">
                      <option value="All">All Client Status</option>
                      <option value="Active Filing">Active Filing</option>
                      <option value="Case-by-Case">Case-by-Case</option>
                      <option value="Inactive (Temporary)">Inactive (Temp)</option>
                      <option value="Inactive (Closed)">Inactive (Closed)</option>
                    </select>
                    <span className={`transition-colors z-10 ${clientStatusColFilter !== 'All' ? 'text-indigo-600' : 'text-slate-400 group-hover:text-indigo-600'}`}>
                      {clientStatusColFilter === 'All' ? 'Client Status' : clientStatusColFilter}
                    </span>
                    <svg className={`h-3 w-3 transition-colors z-10 pointer-events-none ${clientStatusColFilter !== 'All' ? 'text-indigo-600' : 'text-slate-300 group-hover:text-indigo-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" />
                    </svg>
                  </div>
                </th>
                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right min-w-[100px]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredClients.length === 0 ? (
                <tr>
                  <td colSpan={8} className="py-20 text-center text-slate-400 font-bold uppercase tracking-widest text-xs">No records found matching filters</td>
                </tr>
              ) : (
                filteredClients.map((client, idx) => (
                  <tr key={client.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-4 py-5">
                      <span className="text-xs font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</span>
                    </td>
                    <td className="px-4 py-5">
                      <p className="text-sm font-black text-slate-900 leading-tight truncate max-w-[160px]">{client.tradeName || '---'}</p>
                    </td>
                    <td className="px-4 py-5">
                      <p className="text-xs font-bold text-slate-500 uppercase truncate max-w-[160px]">{client.legalName}</p>
                    </td>
                    <td className="px-4 py-5 whitespace-nowrap">
                      <p className="text-xs font-black text-slate-700">{client.mobile || '---'}</p>
                    </td>
                    <td className="px-4 py-5 whitespace-nowrap">
                       <span className="text-[11px] font-black text-indigo-600 font-mono tracking-widest">{client.gstProfile?.gstin}</span>
                    </td>
                    <td className="px-4 py-5 text-center whitespace-nowrap">
                      <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider ${
                        client.gstProfile?.gstStatus === 'Active' ? 'bg-green-100 text-green-700' : 
                        client.gstProfile?.gstStatus === 'Suspended' ? 'bg-amber-100 text-amber-700' : 'bg-red-100 text-red-700'
                      }`}>
                        {client.gstProfile?.gstStatus || 'N/A'}
                      </span>
                    </td>
                    <td className="px-4 py-5 text-center whitespace-nowrap">
                      <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider ${
                        client.status === 'Active Filing' ? 'bg-blue-100 text-blue-700' : 
                        client.status === 'Case-by-Case' ? 'bg-purple-100 text-purple-700' : 'bg-slate-100 text-slate-600'
                      }`}>
                        {client.status}
                      </span>
                    </td>
                    <td className="px-4 py-5 text-right whitespace-nowrap">
                      <div className="flex items-center justify-end gap-2 relative">
                        {/* 1. View Icon */}
                        <button 
                          onClick={() => { setSelectedClient(client); setIsDetailModalOpen(true); }}
                          className="h-8 w-8 rounded-lg bg-white border border-slate-200 text-slate-400 hover:text-indigo-600 hover:border-indigo-200 shadow-sm flex items-center justify-center transition-all"
                          title="View Details"
                        >
                          <svg className="h-4.5 w-4.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 12z" /></svg>
                        </button>

                        {/* 2. Three Dot Icon */}
                        <div className="relative">
                          <button 
                            onClick={() => setActiveMenuId(activeMenuId === client.id ? null : client.id)}
                            className="h-8 w-8 rounded-lg bg-white border border-slate-200 text-slate-400 hover:text-slate-900 hover:border-slate-300 shadow-sm flex items-center justify-center transition-all"
                          >
                            <svg className="h-4.5 w-4.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z" /></svg>
                          </button>

                          {activeMenuId === client.id && (
                            <>
                              <div className="fixed inset-0 z-40" onClick={() => setActiveMenuId(null)} />
                              <div className="absolute right-0 mt-2 w-56 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 p-1.5 animate-in zoom-in-95 overflow-hidden">
                                <button 
                                  onClick={() => { setSelectedClient(client); setTempPassword(client.gstProfile?.password || ''); setIsLoginModalOpen(true); setActiveMenuId(null); }}
                                  className="w-full flex items-center gap-3 px-3 py-2.5 text-xs font-black uppercase tracking-widest text-slate-600 hover:bg-slate-50 rounded-xl transition-colors"
                                >
                                  <svg className="h-4 w-4 text-indigo-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
                                  Portal Login
                                </button>
                                <button 
                                  onClick={() => handleShare('Client Credentials', getCredText(client))}
                                  className="w-full flex items-center gap-3 px-3 py-2.5 text-xs font-black uppercase tracking-widest text-slate-600 hover:bg-slate-50 rounded-xl transition-colors"
                                >
                                  <svg className="h-4 w-4 text-blue-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
                                  Share Credentials
                                </button>
                                <button 
                                  onClick={() => handleShare('GST Certificate', getCertText(client), client.gstProfile?.certificateUrl)}
                                  className="w-full flex items-center gap-3 px-3 py-2.5 text-xs font-black uppercase tracking-widest text-slate-600 hover:bg-slate-50 rounded-xl transition-colors"
                                >
                                  <svg className="h-4 w-4 text-amber-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                                  Share Certificate
                                </button>
                              </div>
                            </>
                          )}
                        </div>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      <GSTClientFormModal isOpen={isGstModalOpen} onClose={() => setIsGstModalOpen(false)} onSave={() => fetchClients()} initialData={selectedClient} />

      {/* COMPREHENSIVE VIEW DETAILS MODAL */}
      {isDetailModalOpen && selectedClient && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
          <div className="w-full max-w-5xl bg-white rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
            {/* Header */}
            <div className="px-10 py-8 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
              <div>
                 <h2 className="text-2xl font-black text-slate-900 tracking-tight leading-none uppercase">{selectedClient.legalName}</h2>
                 <p className="text-sm font-bold text-slate-500 mt-2 uppercase tracking-widest">{selectedClient.tradeName || 'No Trade Name Registered'}</p>
              </div>
              <div className="flex items-center gap-2">
                <button onClick={() => handleEdit(selectedClient)} className="h-10 px-6 bg-indigo-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg shadow-indigo-100 hover:bg-slate-900 transition-all">Edit</button>
                <button onClick={() => setIsDetailModalOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-200 transition-colors">
                  <svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            </div>

            {/* Detailed Content */}
            <div className="p-10 overflow-y-auto no-scrollbar max-h-[75vh] space-y-12">

               {/* 1. Basic & Registration Profile */}
               <section>
                  <h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 mb-6 flex items-center gap-3">
                    Business Profile <div className="h-px flex-1 bg-slate-100" />
                  </h4>
                  <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                     <div className="space-y-1">
                        <p className="text-[9px] font-black uppercase text-slate-400">GSTIN Identifier</p>
                        <p className="text-base font-black text-indigo-600 font-mono tracking-widest">{selectedClient.gstProfile?.gstin}</p>
                     </div>
                     <div className="space-y-1">
                        <p className="text-[9px] font-black uppercase text-slate-400">Legal Status</p>
                        <p className="text-base font-black text-slate-900">{selectedClient.status}</p>
                     </div>
                     <div className="space-y-1">
                        <p className="text-[9px] font-black uppercase text-slate-400">Mobile Number</p>
                        <p className="text-base font-black text-slate-900">{selectedClient.mobile || 'N/A'}</p>
                     </div>
                     <div className="space-y-1">
                        <p className="text-[9px] font-black uppercase text-slate-400">Email Address</p>
                        <p className="text-sm font-black text-slate-900 truncate">{selectedClient.email || 'Not Provided'}</p>
                     </div>
                     <div className="space-y-1">
                        <p className="text-[9px] font-black uppercase text-slate-400">Registration Date</p>
                        <p className="text-base font-black text-slate-900">{selectedClient.gstProfile?.regDate || 'N/A'}</p>
                     </div>
                     <div className="space-y-1">
                        <p className="text-[9px] font-black uppercase text-slate-400">Registration Type</p>
                        <p className="text-base font-black text-slate-900">{selectedClient.gstProfile?.regType}</p>
                     </div>
                     <div className="space-y-1">
                        <p className="text-[9px] font-black uppercase text-slate-400">Filing Frequency</p>
                        <p className="text-base font-black text-slate-900">{selectedClient.gstProfile?.filingFreq}</p>
                     </div>
                     <div className="space-y-1">
                        <p className="text-[9px] font-black uppercase text-slate-400">Constitution</p>
                        <p className="text-base font-black text-slate-900">{selectedClient.gstProfile?.constitution}</p>
                     </div>
                     {selectedClient.gstProfile?.gstStatus === 'Cancelled' && (
                       <div className="space-y-1">
                          <p className="text-[9px] font-black uppercase text-red-400">Cancellation Date</p>
                          <p className="text-base font-black text-red-600">{selectedClient.gstProfile?.cancelDate || 'N/A'}</p>
                       </div>
                     )}
                  </div>
               </section>

               {/* 2. Portal Access Security */}
               <section>
                  <h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 mb-6 flex items-center gap-3">
