                  <button onClick={() => handleNativeShare('Full Client Data', getFullShareText(selectedClient))} className="flex items-center gap-4 h-14 px-10 bg-indigo-600 text-white rounded-2xl font-black text-xs uppercase tracking-[0.15em] shadow-xl shadow-indigo-100 hover:bg-slate-900 transition-all active:scale-95 group">
