                               {showPassInView ? <svg className="h-4.5 w-4.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg> : <svg className="h-4.5 w-4.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029" /></svg>}
                            </button>
                            <button onClick={() => setIsEditingPassword(true)} className="h-9 w-9 flex items-center justify-center rounded-xl bg-white text-slate-400 hover:text-indigo-600 shadow-sm transition-all" title="Edit Password Only">
                               <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                            </button>
                          </div>
                        )}
                     </div>

                     {/* Portal Actions */}
                     <div className="flex gap-2 shrink-0">
                        <button onClick={() => openPortalLogin(selectedClient)} className="h-full px-5 sm:px-6 bg-indigo-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg shadow-indigo-100 hover:bg-slate-900 transition-all flex items-center gap-2 min-h-[50px]">
                           <svg className="h-4.5 w-4.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
                           Login
                        </button>
                        <button onClick={() => shareViaWhatsApp(`*Credential Share*\nID: ${selectedClient.gstProfile?.username}\nPass: ${selectedClient.gstProfile?.password}`)} className="h-full w-12 sm:w-14 flex items-center justify-center rounded-2xl bg-white border border-slate-200 text-slate-400 hover:text-indigo-600 shadow-sm transition-all">
                           <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
                        </button>
                     </div>
                  </div>
               </section>

               {/* 3. Documentation Section */}
               <section>
                  <h4 className="text-[10px] sm:text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 mb-6 flex items-center gap-3">Documentation <div className="h-px flex-1 bg-slate-100" /></h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 sm:gap-8">
                     <div className="space-y-2">
                        <p className="text-[9px] font-black uppercase text-slate-400 mb-1.5 block">Registration Certificate</p>
                        <div className="flex items-center justify-between p-4 bg-slate-50 border border-slate-200 rounded-2xl">
                           <div className="flex items-center gap-3 min-w-0">
                              <div className="h-10 w-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center shadow-lg shrink-0"><svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg></div>
                              <span className="text-xs font-bold text-slate-700 truncate">{selectedClient.gstProfile?.certificateUrl || 'No file uploaded'}</span>
                           </div>
                           <button onClick={() => shareViaWhatsApp(`Download GST Certificate: ${selectedClient.gstProfile?.certificateUrl}`)} className="h-9 w-9 flex items-center justify-center rounded-xl bg-white border border-slate-200 text-slate-400 hover:text-indigo-600 shadow-sm shrink-0"><svg className="h-4.5 w-4.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M8.684 13.342C8.886 12.938 9 12.482 9 12" /></svg></button>
                        </div>
                     </div>
                     <div className="space-y-2"><p className="text-[9px] font-black uppercase text-slate-400 mb-1.5 block">Principal Address</p><div className="text-sm font-bold text-slate-600 leading-relaxed bg-slate-50 p-4 rounded-2xl border border-slate-200 min-h-[60px]">{selectedClient.gstProfile?.address || 'N/A'}</div></div>
                  </div>
               </section>

            </div>

            {/* Fixed Bottom Multi-Channel Sharing */}
            <div className="p-6 sm:p-8 border-t border-slate-100 bg-slate-50/50 flex flex-col gap-6 shrink-0">
               <div className="flex items-center justify-between gap-4"><div className="flex-1 h-px bg-slate-200" /><span className="text-[9px] sm:text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] whitespace-nowrap px-2">Professional Share Channel</span><div className="flex-1 h-px bg-slate-200" /></div>
               <div className="flex flex-wrap items-center justify-center gap-3 sm:gap-4">
                  <button onClick={() => shareViaWhatsApp(getFullShareText(selectedClient))} className="flex items-center gap-3 h-12 sm:h-14 px-6 sm:px-8 bg-white border border-slate-200 rounded-2xl text-[10px] sm:text-[11px] font-black uppercase tracking-widest text-slate-600 hover:border-green-500 hover:text-green-600 transition-all shadow-sm">
                     <svg className="h-5 w-5" fill="currentColor" viewBox="0 0 24 24"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L0 24l6.335-1.662c1.72.94 3.659 1.437 5.634 1.437h.005c6.558 0 11.894-5.335 11.897-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg>
                     WhatsApp Share
                  </button>
                  <button onClick={() => shareViaEmail(`Professional Profile: ${selectedClient.legalName}`, getFullShareText(selectedClient))} className="flex items-center gap-3 h-12 sm:h-14 px-6 sm:px-8 bg-white border border-slate-200 rounded-2xl text-[10px] sm:text-[11px] font-black uppercase tracking-widest text-slate-600 hover:border-red-500 hover:text-red-600 transition-all shadow-sm">
                     <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" /></svg>
                     Email Profile
                  </button>
                  <button onClick={() => handleNativeShare('Full Client Data', getFullShareText(selectedClient))} className="flex items-center gap-4 h-12 sm:h-14 px-8 sm:px-10 bg-indigo-600 text-white rounded-2xl font-black text-[10px] sm:text-xs uppercase tracking-[0.15em] shadow-xl shadow-indigo-100 hover:bg-slate-900 transition-all active:scale-95 group shrink-0">
                     <svg className="h-5 w-5 group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                     Share All Details
                  </button>
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default GstMasterPortfolio;
